#!/usr/bin/env python3
from pathlib import Path
from datetime import datetime
import re, shutil, py_compile, base64
ROOT=Path("/home/ubuntu/sports-hulk")
APP=ROOT/"app.py"
MOD=ROOT/"hulk_final_ui.py"
if not APP.exists(): raise SystemExit("app.py not found")
backup=ROOT/f"app.py.pre_final_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
shutil.copy2(APP,backup)
MOD.write_text(base64.b64decode("").decode())
text=APP.read_text()
imp="from hulk_final_ui import nav as hulk_nav, feature as render_hulk_feature_page, dashboard as render_dashboard_boost, css as inject_hulk_final_css"
if imp not in text:
    a="import streamlit as st"
    if a not in text:
        shutil.copy2(backup,APP); raise SystemExit("Streamlit import not found; restored")
    text=text.replace(a,a+"\n"+imp,1)
def add_after(old,new):
    global text
    if f'"{new}"' in text:return
    n=f'"{old}",'
    if n in text:text=text.replace(n,n+f'\n        "{new}",',1)
add_after("Best Bets","Parlay Center")
add_after("MLB Best Bets","MLB Parlays")
add_after("NFL Best Bets","NFL Parlays")
add_after("CFB Best Bets","CFB Parlays")
if '"My Leagues"' not in text:
    add_after("League Settings","My Leagues")
    if '"My Leagues"' not in text:add_after("Fantasy Dashboard","My Leagues")
add_after("Sleepers","Waiver Wire Weekly")
add_after("Waiver Wire Weekly","Lineup")
pat=re.compile(r'page\s*=\s*st\.sidebar\.radio\(\s*"Navigation",\s*menu,\s*label_visibility\s*=\s*"collapsed"\s*\)',re.S)
if pat.search(text): text=pat.sub("page = hulk_nav(menu, mode)",text,count=1)
elif "page = hulk_nav(menu, mode)" not in text:
    shutil.copy2(backup,APP); raise SystemExit("Navigation block not recognized; restored")
hook="\ninject_hulk_final_css()\nrender_dashboard_boost(mode, page)\nif render_hulk_feature_page(mode, page):\n    st.stop()\n"
if "render_hulk_feature_page(mode, page)" not in text:
    text=text.replace("page = hulk_nav(menu, mode)","page = hulk_nav(menu, mode)"+hook,1)
APP.write_text(text)
try:
    py_compile.compile(str(APP),doraise=True); py_compile.compile(str(MOD),doraise=True)
except Exception as e:
    shutil.copy2(backup,APP); raise SystemExit(f"Compile failed; restored. {e}")
print("="*72)
print("SPORTS HULK FINAL UI INSTALLER")
print("="*72)
print("BACKUP:",backup)
print("COMPILE: PASS")
print("ADDED: mobile quick-nav, dashboard WOW strip, Parlay Center, MLB/NFL/CFB Parlays,")
print("       My Leagues, Waiver Wire Weekly, Lineup")
print("RESULT: PASS")
